{
  "S1_split_unit": {
    "code": "A",
    "quote": "It should be also noted that the training samples and testing samples of each category were divided according to 8:2.",
    "location": "p.11",
    "reason": "The paper describes dividing each category into training and testing sets by an 8:2 ratio on the sample level, and no mention of splitting by recording file, bearing, or operating condition. This implies window/sample-level random splitting where windows from the same recording can appear in both sets."
  },
  "S2_validation": {
    "code": "A",
    "quote": "It should be also noted that the training samples and testing samples of each category were divided according to 8:2.",
    "location": "p.11",
    "reason": "The paper only mentions training and testing sets; no validation set is mentioned anywhere. Table 3 also only lists training and testing set sizes."
  },
  "S3_checkpoint_rule_code": {
    "code": "N",
    "quote": "",
    "location": "",
    "reason": "The provided code file is NO_CODE, so there is no public code to inspect for checkpoint selection."
  },
  "S4a_text_discloses": {
    "code": "P",
    "quote": "Multiple repeated experiments were performed to further demonstrate the effectiveness of SMUKF-aided DBN",
    "location": "p.8",
    "reason": "The text mentions repeated experiments and convergence (e.g., 'stable loss when the number of iterations is 200' on p.12) but does not explicitly state whether the final reported model is the last epoch, best on validation, etc. It only gives vague statements about repeated runs and convergence."
  },
  "S4b_text_matches_code": {
    "code": "N",
    "quote": "",
    "location": "",
    "reason": "No public code is available (NO_CODE), so consistency between text and code cannot be assessed."
  },
  "S5_runs": {
    "code": "U",
    "quote": "",
    "location": "",
    "reason": "The paper states 'multiple repeated experiments were performed' but does not provide an exact number of repetitions. Search for specific run counts yielded no numeric value."
  },
  "S5_spread_reported": {
    "code": "Y",
    "quote": "The violin chart is the combination of the box graph and kernel density, which displays the overall distribution and the above statistical information (upper adjacent value, third quartile, median, first quartile, and lower adjacent value) of the diagnosis results.",
    "location": "p.8",
    "reason": "The paper reports distributions via violin/box plots and also provides standard deviations in tables (e.g., Table 4, Table 7) with ± std values."
  },
  "S6_metrics": {
    "code": "F",
    "quote": "Four metrics should be evaluated to assess the practicability and feasibility of the proposed method in low-speed bearing diagnosis including IoU, Accuracy, Recall, and F-score.",
    "location": "p.7",
    "reason": "The reported metrics include Accuracy, Recall, and F-score (an F1-type measure), but no confusion matrix is presented."
  },
  "S7_noise_protocol": {
    "code": "U",
    "quote": "Simulations about the noise interference of various intensities (6 dB, 4 dB, 2 dB, 0 dB, -2 Db, and -4 dB) were performed to compare the experimental data acquired through the proposed method (SMUKF-aided DBN), DBN with DCWPT...",
    "location": "p.12",
    "reason": "The noise experiment adds noise to the data at different intensities, but it is not specified whether training used clean data and testing used noisy data (T), or both used noisy data (B), or other settings. Thus the protocol is unclear and coded as U."
  },
  "S8_traceability": {
    "code": "0",
    "quote": "The data that has been used is confidential.",
    "location": "p.15",
    "reason": "No code, trained weights, training logs/curves, or raw result files are publicly provided. The data availability statement says the data is confidential, and the code file is NO_CODE."
  }
}
